    table: [["Website Included", "Yes (branded)", "No (app only)"], ["Menu Management", "Yes (with SEO)", "Yes"], ["Order Management", "Yes", "Yes"], ["Delivery Integration", "Yes (multiple providers)", "Yes"], ["Payment Gateways", "JazzCash, EasyPaisa, Stripe, Bank Transfer", "Limited"], ["Customer Database", "100% yours (exportable)", "Limited export"], ["Email Marketing", "Unlimited (included)", "No"], ["SMS Marketing", "Included", "No"], ["Social Media Tools", "Scheduling + analytics", "Manual only"], ["Google Visibility", "Top 10 rankings", "None (app-only)"], ["Customer Reviews", "Managed on site", "Limited"], ["Loyalty Program", "Built-in", "No"], ["Analytics Dashboard", "Advanced", "Basic"], ["Design Customization", "30+ restaurant templates", "Limited"], ["Monthly Cost", "PKR 4,500–55,000", "PKR 5,000–15,000"], ["Delivery Commission", "None (your choice of provider)", "Embedded"], ["Year 1 Total", "PKR 135,000–825,000", "PKR 60,000–180,000 + delivery fees"]],
    whyWeWin: ["You own your customers, not an app. Ordrz customers are \"Ordrz customers.\" MatjarX customers are YOUR customers. You email them. You call them. You build loyalty.", "You rank in Google. When someone searches \"best biryani Karachi\" or \"restaurant near me,\" they find your MatjarX website. Ordrz users are invisible in search results.", "You reduce delivery app dependency. Ordrz encourages using delivery apps (Foodpanda, Uber Eats). MatjarX includes order placement on YOUR website. Direct orders = no commission cut.", "Your online presence is professional. Ordrz is an order app. Your restaurant deserves a real website with:\n- Beautiful food photos\n- Your story and values\n- Reservations + online ordering together\n- Customer testimonials\n- Blog (recipes, events, specials)", "Example: A mid-range restaurant in Lahore:", "Ordrz approach:\n- Ordrz: PKR 8,000/month\n- Delivery app fees (Foodpanda, Uber): 25-30% per order\n- 200 orders/month × PKR 1,000 × 25% = PKR 50,000/month commission\n- Google Ads (to get customers): PKR 15,000/month\n- No email marketing (Ordrz limitation)\n- No brand-building online presence\n- Total: PKR 73,000/month in visible + hidden costs", "MatjarX approach:\n- MatjarX Boost: PKR 15,600/month (includes website, email, social, analytics)\n- Direct orders on website (no commission)\n- 200 orders × 5% higher margin (no app commission) = PKR 10,000 extra profit/month\n- Organic search traffic (reduced ad spend): PKR 0–5,000/month (if ads used at all)\n- Total: PKR 15,600/month + organic profits", "Savings: PKR 57,400/month (PKR 688,800/year). Plus you own your brand.", "You rank for local keywords. Restaurant searches are local. \"Best restaurant Karachi\" or \"biryani near me.\" MatjarX sites rank for these. Ordrz doesn't. Result? MatjarX restaurants get free Google traffic. Ordrz restaurants buy ads."],
    checklist: [{ title: "Professional Website", body: "Your restaurant looks premium, not like an app listing." }, { title: "Own Your Customer Data", body: "Email past customers about new dishes, specials, events." }, { title: "Rank in Google", body: "Show up when people search for restaurants near them. Organic traffic = free customers." }, { title: "Multiple Revenue Streams", body: "Website orders (no commission) + delivery apps (if you choose) + reservations + catering." }, { title: "Build Your Brand", body: "Every interaction strengthens YOUR brand, not the Ordrz brand." }],
