const MAJOR_RIVALS: RivalKey[] = ['wix', 'squarespace', 'godaddy']

// The 3 majors cross-link to each other (the design handoff's original
// behaviour, unchanged). Every one of the 39 added rivals cross-links to
// the 3 majors instead of all 41 other rivals — same bounded-list approach
// as otherCitiesFor, since listing every alternative would be unusable.
export function otherComparisonsFor(key: RivalKey) {
  const picks = MAJOR_RIVALS.includes(key)
    ? MAJOR_RIVALS.filter((k) => k !== key)
    : MAJOR_RIVALS
  const cards = picks.map((k) => ({
    title: `MatjarX vs ${RIVAL_DATA[k].name}`,
    body: RIVAL_DATA[k].intro[0],
    href: routes.compare(k),
  }))
  return cards.concat([{ title: 'All alternatives', body: 'Every option available to a Pakistani business, side by side.', href: routes.alternatives }])
}
